#!/bin/zsh
# Pulls from the headset the room.json generated by RoomJsonExporter (unity-tools), to use the real room in the Editor.
# Usage: 70-pull-room-json.sh com.yourcompany.helloworld [dest.json]
set -euo pipefail
source "$(dirname "${(%):-%x}")/common.sh"

pkg="${1:-}"; [[ -n "$pkg" ]] || { fail "Usage: $0 <Unity app package name> [dest.json]"; exit 1; }
dest="${2:-${LPM_ROOT}/unity-tools/room.json}"
adb="$(adb_bin)" || { fail "adb not found"; exit 1; }
serial="$(quest_serial)" || { fail "no authorized headset on adb"; exit 1; }
src="/sdcard/Android/data/${pkg}/files/room.json"
"$adb" -s "$serial" pull "$src" "$dest"
ok "Room saved to $dest ($(wc -c < "$dest" | tr -d ' ') bytes)"
info "In Unity: drag the JSON into Assets/, then on the MRUK component → Scene Settings → Data Source = Device With Json Fallback → Scene Jsons = room.json"
